+  return [
+    {
+      name: 'catalog_search',
+      description:
+        'Search the catalog for items by name (case-insensitive) with pagination.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          query: {
+            type: 'string',
+            description: 'Search query matched case-insensitively against item names.',
+          },
+          offset: {
+            type: 'integer',
+            default: 0,
+            description: 'Number of matching results to skip (default 0).',
+          },
+          limit: {
+            type: 'integer',
+            minimum: 1,
+            maximum: 5,
+            default: 2,
+            description: 'Maximum number of results to return, 1-5 (default 2).',
+          },
+        },
+        required: ['query'],
+      },
+      annotations: {
+        readOnlyHint: true,
+        destructiveHint: false,
+        idempotentHint: true,
+        openWorldHint: false,
+      },
+    },
+  ];
+}
+
+function validateArgs(args) {
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Arguments must be an object');
+  }
+  for (const key of Object.keys(args)) {
+    if (!ALLOWED_ARGS.has(key)) {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+  if (!('query' in args) || typeof args.query !== 'string') {
+    throw new Error('query is required and must be a string');
+  }
+  let offset = 0;
+  if ('offset' in args) {
+    if (!Number.isInteger(args.offset) || args.offset < 0) {
+      throw new Error('offset must be a non-negative integer');
+    }
+    offset = args.offset;
+  }
+  let limit = 2;
+  if ('limit' in args) {
+    if (!Number.isInteger(args.limit) || args.limit < 1 || args.limit > 5) {
+      throw new Error('limit must be an integer between 1 and 5');
+    }
+    limit = args.limit;
+  }
+  return { query: args.query, offset, limit };
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'catalog_search') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+  const { query, offset, limit } = validateArgs(args);
+
+  const needle = query.toLowerCase();
+  const matches = items.filter((item) =>
+    String(item.name).toLowerCase().includes(needle)
+  );
+  const total = matches.length;
+  const slice = matches.slice(offset, offset + limit);
+  const end = offset + limit;
+  const hasMore = end < total;
+
+  const result = {
+    results: slice,
+    offset,
+    limit,
+    total,
+    count: slice.length,
+    has_more: hasMore,
+  };
+  if (hasMore) {
+    result.next_offset = end;
+  }
+
+  return {
+    content: [{ type: 'text', text: JSON.stringify(result) }],
+  };
